const knownSubscriptions = [
  { name: 'Netflix', category: 'Giải trí', expected_range: [70000, 260000], currency: 'VND' },
  { name: 'Spotify', category: 'Âm nhạc', expected_range: [59000, 85000], currency: 'VND' },
