  { name: 'Disney+', category: 'Giải trí', expected_range: [139000, 360000], currency: 'VND' },
  { name: 'FPT Play', category: 'Giải trí', expected_range: [49000, 120000], currency: 'VND' },
  { name: 'Viettel', category: 'Viễn thông', expected_range: [50000, 500000], currency: 'VND' },
  { name: 'VNPT', category: 'Viễn thông', expected_range: [100000, 500000], currency: 'VND' },
  { name: 'Fiber', category: 'Internet', expected_range: [150000, 500000], currency: 'VND' }
];

return [{
  json: {
    known_subscriptions: knownSubscriptions,
    current_month: new Date().toISOString().slice(0, 7),
    report_date: new Date().toLocaleString('en-US', { timeZone: 'Asia/Ho_Chi_Minh' })
  }
}];

// Parse bank emails for recurring charges
// Tìm các giao dịch định kỳ từ email ngân hàng

// TODO: Thực tế cần Email Trigger node để fetch emails
// Đây là mock data - thay thế bằng email parsing thực tế

const bankTransactions = [
  // Mock data - ví dụ giao dịch hàng tháng
  { date: '2026-05-01', merchant: 'Netflix', amount: 129000, description: 'Netflix Subscription' },
  { date: '2026-05-03', merchant: 'Spotify', amount: 59000, description: 'Spotify Premium' },
  { date: '2026-05-05', merchant: 'Google One', amount: 79000, description: 'Google Storage' },
  { date: '2026-05-01', merchant: 'Viettel', amount: 200000, description: 'Mobile Plan' }
];

const currentSubscriptions = $('Fetch Subscriptions from Sheets').all()[0]?.json || [];
const knownSubs = $('Load Known Subscriptions').first().json.known_subscriptions;

return [{
  json: {
    transactions: bankTransactions,
    current_subscriptions: currentSubscriptions,
    known_subscriptions: knownSubs
  }
}];

// Analyze subscriptions - find changes
const data = $input.first().json;
const transactions = data.transactions;
const currentSubs = data.current_subscriptions;
const knownSubs = data.known_subscriptions;

const report = {
  total_monthly_cost: 0,
  new_subscriptions: [],
  price_changes: [],
  cancelled_subscriptions: [],
  all_subscriptions: [],
  warnings: []
};

// Match transactions with known subscriptions
for (const tx of transactions) {
  const matched = knownSubs.find(k => 
    k.name.toLowerCase().includes(tx.merchant.toLowerCase()) ||
    tx.merchant.toLowerCase().includes(k.name.toLowerCase())
  );

  const category = matched ? matched.category : 'Khác';

  // Find in current subscriptions
  const existing = currentSubs.find(s => 
    s.Name?.toLowerCase() === tx.merchant.toLowerCase() ||
    s.Name?.toLowerCase().includes(tx.merchant.toLowerCase())
  );

  if (!existing) {
    // New subscription found
    report.new_subscriptions.push({
      name: tx.merchant,
      amount: tx.amount,
      category,
      first_charged: tx.date
    });
  } else if (existing) {
    // Check for price change
    const existingAmount = parseFloat(existing.Amount) || 0;
    if (existingAmount > 0 && Math.abs(tx.amount - existingAmount) / existingAmount > 0.1) {
      const changePercent = ((tx.amount - existingAmount) / existingAmount * 100).toFixed(1);
      report.price_changes.push({
        name: tx.merchant,
        old_amount: existingAmount,
        new_amount: tx.amount,
        change_percent: parseFloat(changePercent),
        direction: tx.amount > existingAmount ? 'increase' : 'decrease'
      });

      if (tx.amount > existingAmount) {
        report.warnings.push(`⚠️ ${tx.merchant} tăng giá: ${changePercent}%`);
      }
    }
  }

  report.total_monthly_cost += tx.amount;
  report.all_subscriptions.push({
    name: tx.merchant,
    amount: tx.amount,
    category,
    last_charged: tx.date
  });
}

// Check for cancelled subscriptions (in current but not in transactions)
const currentNames = currentSubs.map(s => s.Name?.toLowerCase());
for (const sub of currentSubs) {
  const stillActive = transactions.some(tx => 
    tx.merchant.toLowerCase().includes(sub.Name?.toLowerCase()) ||
    sub.Name?.toLowerCase().includes(tx.merchant.toLowerCase())
  );
  if (!stillActive && sub.Status === 'active') {
    report.cancelled_subscriptions.push({
      name: sub.Name,
      last_amount: parseFloat(sub.Amount) || 0,
      last_charged: sub.Last_Charged
    });
  }
}

// Check for unused subscriptions (> 30 days)
for (const sub of currentSubs) {
  if (sub.Status === 'active' && sub.Last_Charged) {
    const lastCharged = new Date(sub.Last_Charged);
    const daysSince = (Date.now() - lastCharged.getTime()) / (1000 * 60 * 60 * 24);
    if (daysSince > 60) {
      report.warnings.push(`💤 ${sub.Name} không sử dụng ${Math.floor(daysSince)} ngày - xem xét hủy?`);
    }
  }
}

return [{
  json: {
    ...report,
    report_date: new Date().toLocaleString('en-US', { timeZone: 'Asia/Ho_Chi_Minh' }),
    month: new Date().toISOString().slice(0, 7)
  }
}];

